function UICultivateStarTeamRatingView:RefreshUI()
    local ratingId = cardComp:GetRatingId()
    local maxRatingId = cardComp:GetMaxRatingId()
    local isMaxRating = ratingId >= maxRatingId

    ---@region 定向作战入口的弹窗
    local directionalTypeVo = CfUtils.GetWholeVo(AutoIds.IdSetting933, "DirectionalTypeVo")
    local data = {}
    for k, v in pairs(directionalTypeVo) do
        data[checkString(v.id)] = {
            times = 2,
            difficulty = checkNumber(ratingId)
        }
    end
    DirectionalFightComponent:SetPlayerPrefs(data)

    self.ImgGrade:LoadSprite(CardUtils.CardRatingPath(ratingId))

    KTool.SetActive(self.TxtMax.gameObject, isMaxRating)
    KTool.SetActive(self.NextRatingTip.gameObject, not isMaxRating)
    ---@type CardUpgradeStarLimitVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting121, "CardUpgradeStarLimitVo", ratingId)
    self.UnlockTip.text = vo.unlockDesc
    if not isMaxRating then
        vo = CfUtils.GetCfVo(AutoIds.IdSetting121, "CardUpgradeStarLimitVo", ratingId + 1)
        self.NextRatingTip.text = localize("下一级升级条件: _desc_", {_desc_ = vo.conditionDesc})
    end
end

function UICultivateStarTeamRatingView:CheckAnimatorPlayComplete()
    if not self._aniRoot then
        self._aniRoot = self.controller.gameObject.transform:Find("Root"):GetComponent(typeof(Animator))
    end
    cs_coroutine.yield_return(self._aniRoot:WaitUntilAniCompleted())
end

